  it('fails on the patched build', () => {
    // With an explicit tag, the JSON schema must still accept an unsigned
    // positive exponent: 1e3 is valid YAML 1.2 JSON-schema float syntax.
    assert.strictEqual(load('!!float 1e3', { schema: JSON_SCHEMA }), 1000);
  });
});
"}, "note": "The change forces a sign in the exponent of the JSON schema's explicit float pattern's first alternative, so an explicit `!!float 1e3` under JSON_SCHEMA now throws 'cannot resolve a node with !<tag:yaml.org,2002:float> explicit tag' instead of loading 1000 (while `!!float .5e3` still works, showing the restriction is accidental)."}
